// Incident RCA & Post-Mortem Payload Extractor
const incId = $json.incident_id || ('INC-' + new Date().toISOString().slice(0,10).replace(/-/g,'') + '-' + Math.floor(Math.random()*1000));
const title = $json.title || 'Automated Incident Remediation Summary';
const rca = $json.root_cause || 'System service disruption detected and resolved by signed SOP.';
const sopId = $json.bound_sop_id || 'SOP_001';
return [{ json: { incident_id: incId, title: title, root_cause: rca, bound_sop_id: sopId, severity: $json.severity || 'HIGH', resolved_at: new Date().toISOString() } }];

// Format Markdown & Generate Backlinks
const markdown = `---
incident_id: ${$json.incident_id}
title: "${$json.title}"
severity: ${$json.severity}
date: ${$json.resolved_at}
--- 

# Incident Report: ${$json.title}

## Root Cause Analysis
${$json.root_cause}

## Remediation Procedure
Executed bound SOP: [[${$json.bound_sop_id}]]
`;
return [{ json: { incident_id: $json.incident_id, markdown_content: markdown, target_file: `incidents/${$json.incident_id}.md` } }];
